	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getActBulkSetR())) ret.add(getActBulkSetR());
		if(!MCCollectionUtil.contains(ret, getAprvBulkSetR())) ret.add(getAprvBulkSetR());
		if(!MCCollectionUtil.contains(ret, getUnschdBulkSetR())) ret.add(getUnschdBulkSetR());
		if(!MCCollectionUtil.contains(ret, getRsltL())) ret.add(getRsltL());
		if(!MCCollectionUtil.contains(ret, getRsltYieldByProdL())) ret.add(getRsltYieldByProdL());
		if(!MCCollectionUtil.contains(ret, getRsltYieldByProdBtnR())) ret.add(getRsltYieldByProdBtnR());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getActBulkSetR()) return "ActBulkSet";
		if(aCnt == getAprvBulkSetR()) return "AprvBulkSet";
		if(aCnt == getUnschdBulkSetR()) return "UnschdBulkSet";
		if(aCnt == getRsltL()) return "Rslt";
		if(aCnt == getRsltYieldByProdL()) return "RsltYieldByProd";
		if(aCnt == getRsltYieldByProdBtnR()) return "RsltYieldByProdBtn";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("ActBulkSet")) return getActBulkSetR();
		if(bId.equals("AprvBulkSet")) return getAprvBulkSetR();
		if(bId.equals("UnschdBulkSet")) return getUnschdBulkSetR();
		if(bId.equals("Rslt")) return getRsltL();
		if(bId.equals("RsltYieldByProd")) return getRsltYieldByProdL();
		if(bId.equals("RsltYieldByProdBtn")) return getRsltYieldByProdBtnR();
		return super.getContainer(bId);
	}

